package org.jsoup.nodes;

import org.jsoup.parser.Tag;
import org.junit.Assert;
import org.junit.Test;

public class TextNodeTest {

    @Test
    public void textNodeConstructorTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        Assert.assertNotNull(textNode);
    }

    @Test
    public void nodeNameTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        Assert.assertEquals("#text", textNode.nodeName());
    }

    @Test
    public void textTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        Assert.assertEquals(text, textNode.text());
    }

    @Test
    public void setTextTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        String newText = "new text";
        textNode.text(newText);
        Assert.assertEquals(newText, textNode.text());
    }

    @Test
    public void getWholeTextTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        Assert.assertEquals(text, textNode.getWholeText());
    }

    @Test
    public void isBlankTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        Assert.assertFalse(textNode.isBlank());
    }

    @Test
    public void splitTextTest() {
        String text = "sample text";
        TextNode textNode = new TextNode(text);
        TextNode splitNode = textNode.splitText(6);
        Assert.assertEquals("sample", textNode.getWholeText());
        Assert.assertEquals(" text", splitNode.getWholeText());
    }

    @Test
    public void createFromEncodedTest() {
        String text = "&#x0041;";
        TextNode textNode = TextNode.createFromEncoded(text, false);
        Assert.assertNotNull(textNode);
        Assert.assertEquals("A", textNode.text());
    }

    @Test
    public void normaliseWhitespaceTest() {
        String text = "      sample        text      ";
        String result = TextNode.normaliseWhitespace(text);
        Assert.assertEquals(" sample text ", result);
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String text = "   sample text";
        String result = TextNode.stripLeadingWhitespace(text);
        Assert.assertEquals("sample text", result);
    }

    @Test
    public void lastCharIsWhitespaceTest() {
        StringBuilder sb = new StringBuilder("sample text ");
        boolean result = TextNode.lastCharIsWhitespace(sb);
        Assert.assertTrue(result);
    }
}
